const now = Date.now();

if (now < (flow.get('adaptBusyUntil') || 0)) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'busy, skip' });
    return null;
}

const trigger = msg.trigger || 'tick';
const pausedUntil = flow.get('adaptPausedUntil') || 0;

if (trigger === 'turnon') {
    flow.set('adaptPausedUntil', 0);
} else if (now < pausedUntil) {
    const left = Math.round((pausedUntil - now) / 60000);
    node.status({ fill: 'grey', shape: 'ring', text: 'manual pause, ' + left + ' min left' });
    return null;
}

const minGain = Number(env.get('MIN_GAIN')) || 0;
const raw = Number(msg.gainRaw);
if (isNaN(raw)) {
    node.status({ fill: 'red', shape: 'ring', text: 'gain sensor NaN' });
    return null;
}
const gain = Math.round(minGain + raw * (100 - minGain) / 100);

if (trigger === 'tick') {
    const cur = msg.bulb && msg.bulb.attributes ? Number(msg.bulb.attributes.brightness) : NaN;
    const last = flow.get('lastBrightness');
    if (!isNaN(cur) && last !== undefined && Math.abs(cur - last) > 13) {
        const pauseMin = Number(env.get('MANUAL_PAUSE')) || 45;
        flow.set('adaptPausedUntil', now + pauseMin * 60000);
        node.status({ fill: 'grey', shape: 'dot', text: 'manual change -> pause ' + pauseMin + ' min' });
        return null;
    }
}

const transition = Number(env.get(trigger === 'turnon' ? 'TRANSITION_CLICK' : 'TRANSITION_AUTO')) || 1;
msg.transition = transition;
msg.gain = gain;
msg.delay = transition * 1000 + 500;

flow.set('lastBrightness', Math.round(gain * 2.55));
flow.set('adaptBusyUntil', now + 2 * transition * 1000 + 5000);

node.status({ fill: 'green', shape: 'dot', text: 'gain ' + gain + '% / ' + (msg.kelvin || '-') + 'K, t=' + transition + 's' });
return msg;

const t = msg.topic;
const p = msg.payload;
const now = Date.now();
const mode = flow.get('mode', 'file') || 'off';
const guardMs = Number(env.get('GUARD_MS')) || 5000;
const guard = flow.get('cmdGuard') || 0;

let on = null, off = null, lux = null, grace = null;

const setMode = (m) => { flow.set('mode', m, 'file'); };
const arm = () => flow.set('cmdGuard', Date.now());
const startGrace = () => {
    const seq = (flow.get('graceSeq') || 0) + 1;
    flow.set('graceSeq', seq);
    grace = { graceSeq: seq, delay: (Number(env.get('GRACE_MINUTES')) || 2) * 60000 };
};

switch (t) {
    case 'init':
        setMode(p === 'on' ? 'manual' : 'off');
        break;

    case 'presence':
        flow.set('lastPresence', p);
        if (p !== 'on') break;
        if (mode === 'veto') break; // ручное вето: миганья датчика игнорируем
        if (mode === 'grace') {
            arm();
            setMode('auto');
            on = { payload: 'grace_reenter' };
        } else if (mode === 'off') {
            lux = msg;
        }
        break;

    case 'lux_ok':
        if (mode === 'off') {
            arm();
            setMode('auto');
            on = { payload: 'auto_on' };
        }
        break;

    case 'idle_auto':
        flow.set('lastPresence', 'off');
        if (mode === 'auto') {
            arm();
            setMode('grace');
            off = { payload: 'auto_off' };
            startGrace();
        } else if (mode === 'veto') {
            setMode('off'); // комната опустела — вето снято
        }
        break;

    case 'idle_manual':
        flow.set('lastPresence', 'off');
        if (mode === 'manual') {
            arm();
            setMode('grace');
            off = { payload: 'manual_idle_off' };
            startGrace();
        } else if (mode === 'veto') {
            setMode('off');
        }
        break;

    case 'grace_expired':
        if (mode === 'grace' && msg.graceSeq === flow.get('graceSeq')) {
            setMode('off');
        }
        break;

    case 'light':
        if (now - guard < guardMs) break;
        if (p === 'on') {
            setMode('manual');
        } else if (p === 'off') {
            // выключили руками, пока датчик видит человека -> вето,
            // иначе обычный off
            setMode(flow.get('lastPresence') === 'on' ? 'veto' : 'off');
        }
        break;
}

node.status({ fill: 'blue', shape: 'dot', text: 'mode: ' + (flow.get('mode', 'file') || 'off') });
return [on, off, lux, grace];

if (flow.get("ReleasedTime") - flow.get("PressedTime") < 500)
{
    msg.payload = "Short press";
    return msg;
}

flow.set("dimming",true);
flow.set("increased",true);
var TransitionTime = env.get("TransitionTime")||60;
msg.payload = {"brightness_move": TransitionTime}
return msg;

flow.set("dimming",true);
flow.set("increased",false);
var TransitionTime = env.get("TransitionTime")|| 60;
msg.payload = {"brightness_move": -TransitionTime}
return msg;

const minutes = msg.lightTimeoutMinutes;

if (typeof minutes !== "number" || isNaN(minutes)) {
    node.error("Неверное значение минут");
    return null;
}

const now = new Date();
const future = new Date(now.getTime() + minutes * 60000);

const iso = future.toISOString(); // cronplus принимает ISO для once jobs

flow.set("lightTimeout", iso, 'file')

msg.payload = {
    command: "add",
    name: "lightTimeout",
    topic: "lightTimeout",
    payloadType: "date",
    expressionType: "cron",
    expression: iso,
    once: true,
    onceDelay: 0
};

return msg;

// Получаем текущий список или создаем новый
let colorList = flow.get("cycleColorList", "memoryOnly") || ["", "", ""];

// Убедимся, что msg.color — это строка, и убираем пробелы
let color = (msg.color || "").trim();

// Добавляем цвет, если payload === true
if (msg.payload === true) {
    if (color && !colorList.includes(color)) {
        // Добавляем в начало списка
        colorList.unshift(color);
        // Ограничиваем список до 3 элементов
        colorList = colorList.slice(0, 3);
    }
}

// Удаляем цвет, если payload === false
else if (msg.payload === false) {
    // Удаляем все вхождения цвета
    colorList = colorList.filter(c => c !== color);
    // Добавляем пустые строки до 3 элементов
    while (colorList.length < 3) {
        colorList.push("");
    }
}

// Обновляем переменную потока
flow.set("cycleColorList", colorList, "memoryOnly");

// Можно вывести текущий список для отладки
msg.cycleColorList = colorList;

// Проверяем, если все значения пустые — отправляем импульс через второй выход
let isEmpty = colorList.every(c => c === "");
if (isEmpty) {
    return [null, msg];
}

// В остальных случаях — обычный выход
return [msg, null];

let switches = msg.switches.map(s => s.entity_id);
let bulbs = msg.bulbs.map(b => b.entity_id);

msg.payload = {
    scene_id: "last_light",
    snapshot_entities: [...switches, ...bulbs]
};

return msg;

const RESTORE_WINDOW_MIN = 60; // в течение этого окна повторный double возвращает свет как было

const sleepOn = msg.sleepState === 'on';
const at = Number(flow.get('snapshotAt', 'file')) || 0;
const fresh = (Date.now() - at) < RESTORE_WINDOW_MIN * 60000;

if (!sleepOn) {
    node.status({ fill: 'blue', shape: 'dot', text: 'goodnight' });
    return [msg, null, null];
}
if (fresh) {
    node.status({ fill: 'green', shape: 'dot', text: 'wake: restore lights' });
    return [null, msg, null];
}
node.status({ fill: 'grey', shape: 'dot', text: 'wake: plain' });
return [null, null, msg];

// Развязанные выключатели и виртуальные/служебные свичи в снапшот не берём:
// восстановление их состояния сценой = команда toggle лампе.
const EXCLUDE_ALL = [
    'switch.wall_switch_livingroom',
    'switch.wall_switch_bedroom',
    'switch.switch_virtual_light_livingroom',
    'switch.switch_virtual_light_bedroom',
    'switch.switch_adaptative_light',
    'switch.switch_sleep_mode'
];

const switches = (msg.switches || []).map(s => s.entity_id).filter(e => !EXCLUDE_ALL.includes(e));
const bulbs = (msg.bulbs || []).map(b => b.entity_id).filter(e => !EXCLUDE_ALL.includes(e));

const snapshot = [...switches, ...bulbs];
if (!snapshot.length) {
    node.warn('Snapshot пуст — проверь labels switch/light в HA');
    node.status({ fill: 'red', shape: 'ring', text: 'empty snapshot' });
    return null;
}

msg.payload = { scene_id: 'last_light', snapshot_entities: snapshot };

flow.set('snapshotAt', Date.now(), 'file');
node.status({ fill: 'blue', shape: 'dot', text: snapshot.length + ' entities' });
return msg;
